fn insert(oline: &Vec<char>, l: usize, nl: &Vec<char>, p: usize, at_pos: usize) -> Vec<char> {
    assert!(l <= oline.len(), "l must not exceed oline length");
    assert!(p <= nl.len(), "p must not exceed nl length");
    assert!(at_pos <= l, "at_pos must be in [0, l]");

    let mut out = Vec::with_capacity(l + p);

    // 1) first at_pos chars of oline
    out.extend_from_slice(&oline[..at_pos]);

    // 2) first p chars of nl
    out.extend_from_slice(&nl[..p]);

    // 3) remaining chars from oline[at_pos..l]
    out.extend_from_slice(&oline[at_pos..l]);

    out
}